def S(base):
    f = sorted(glob.glob(os.path.join(SH, base + '-[0-9][0-9][0-9][0-9].png')))
    assert f, base
    return os.path.basename(f[-1])


def T(*bases):
    ts = [(lambda f: f[-8:-6] + ':' + f[-6:-4])(S(b)) for b in bases]
    a, z = min(ts), max(ts)
    return f'(그림 찍은 시각 10월 12일 {a}' + ('' if a == z else f'–{z}') + ')'


